using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CastOrbCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/CastOrbCustomDescription", order = 0)]
public class CastOrbCustomDescription : CustomBattleActionDescription
{
	private const string corruptedOrionCastOrbActionBaseID = "CorruptedOrionCastOrbActionBase";

	[SerializeField]
	private bool corruptedOrion;

	[SerializeField]
	[ShowIf("corruptedOrion")]
	private BattleAction corruptedOrionToGetDescription;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string format = (corruptedOrion ? base.localizationManager.GetLocalizedString("CorruptedOrionCastOrbActionBase") : base.localizationManager.GetLocalizedCastOrbActionBase());
		BattleAction battleAction2 = (corruptedOrion ? corruptedOrionToGetDescription : battleAction);
		string localizedString = base.localizationManager.GetLocalizedString(battleAction2.BaseBattleActionData.ActionIDDescription);
		string firstArgument = Smart.Format(format, localizedString);
		return base.localizationManager.GetLocalizedXTimesFormatted(firstArgument, GetFinalAmountWithoutEquation(amountModified));
	}
}
